`,zw={nauja:"🆕",pataisyta:"🔧",pakeista:"✨"},Ww={nauja:"Nauja",pataisyta:"Pataisyta",pakeista:"Pakeista"},$i=[{data:"2026-08-25",versija:"2026-08-25c",antraste:"Žaidimas atsidaro kelis kartus greičiau",eilutes:[{tipas:"pakeista",tekstas:"Žaidimas nebelaukia, kol atsisiųs visi piešiniai. Anksčiau prieš parodant ūkį būdavo parsiunčiama 11 MB, ir telefonu su mobiliuoju internetu tai truko apie 29 sekundes tuščio ekrano. Dabar ūkis atsidaro maždaug per 7, o piešiniai atkeliauja jam jau veikiant."},{tipas:"pataisyta",tekstas:"Senasis tapytas pasaulis (6,8 MB) buvo siunčiamas kiekvieną kartą, nors jo reikia tik tada, kai neatsisiunčia Lietuvos žemėlapis. Dabar jis parsiunčiamas tik tuo atveju."},{tipas:"pataisyta",tekstas:"Svečiuose paspaudus draugo katiną žaidimas apsimesdavo, kad pagavai peles ir gavai deimantų — nors į savo krepšį negaudavai nieko. Dabar tiesiog pasako, kad tai draugo katinas."}]},{data:"2026-08-25",versija:"2026-08-25b",antraste:"Nauji piešiniai pagaliau matomi ir krautuvėje",eilutes:[{tipas:"pataisyta",tekstas:"Krautuvėje kviečiai, bulvės, morkos ir salotos buvo rodomos senu piešiniu, nors ūkyje jau seniai atrodo kitaip. Dabar kortelėje matai TĄ PATĮ augalą, kokį matysi lauke."},{tipas:"pataisyta",tekstas:"Deimantų medis vėl piešiamas savo nauju piešiniu. Jam buvo paliktas senas, trumpesnis kelias, kuris nespėdavo net paklausti, ar piešinys yra."},{tipas:"nauja",tekstas:"Šešios žuvys (karosas, karpis, lynas, skersnukis, ūsorius, žuvinė ožka) gavo savo piešinius — matomi krautuvėje ir sandėlyje."}]},{data:"2026-08-25",antraste:"Naujas ūkio vaizdas ir vienas katinas vietoj dviejų",eilutes:[{tipas:"nauja",tekstas:"Nauji piešiniai: ūkininko namas, tvartas, garažas ir šiltnamis — kiekvienas iš keturių pusių; kviečiai, bulvės, morkos ir salotos su visomis augimo stadijomis; šešios žuvys, tvenkinys ir naujos žemės plytelės."},{tipas:"pakeista",tekstas:"Kačiukas nebeužima plytelės. Nuo šiol jis vaikšto po ūkį ir gaudo peles, o deimantus pasiimi paspaudęs patį katiną. Kas jį jau turi, plytelę atgauna laisvą — viskas kita (7 parų darbas, kasdien 1 💎) lieka kaip buvę."},{tipas:"pataisyta",tekstas:"Ūkyje matėsi DU katinai: vienas stovėdavo ant savo plytelės, kitas vaikščiojo. Dabar jis vienas — ir tik tam, kas Kačiuką nusipirko."},{tipas:"pataisyta",tekstas:"Katinas nebevaikšto vandeniu ir miške — tik ūkio žeme, kaip ir dera katei."},{tipas:"pataisyta",tekstas:"Ką tik nusipirktas Kačiukas pasirodo iš karto. Anksčiau jis atsirasdavo tik tada, kai ūkyje atsitiktinai pasikeisdavo kas nors kita."}]},{data:"2026-08-24",versija:"2026-08-24b",antraste:"Ūkis nebestovi ne savo žemėje",eilutes:[{tipas:"pataisyta",tekstas:"Didžiausia šio atnaujinimo pataisa. Uždėjus tikrą Lietuvos žemėlapį ant jau esančio ūkio, dalis laukų atsidurdavo ant ežero ar miške. Plytelė tapdavo pusiau ūkio, pusiau vandens: atrodydavo kaip suartas laukas, bet dirbti jos neleisdavo, užtat ant jos buvo galima žvejoti. Dabar ūkis pats atsitaiso — toks darbas persikelia į dirbamą žemę su visu turiniu, o ežeras lieka ežeru. Nieko neprarandama: hektarų, laukų ir pasėlių lieka tiek pat."},{tipas:"pataisyta",tekstas:"Miške augančiu miško medžiu pagaliau galima pasirūpinti: palaistyti, nuvalyti kenkėjus, išravėti ir patręšti. Anksčiau visi įrankiai ten atsakydavo, kad čia miškas — nors medis kaip tik ten ir turi augti."},{tipas:"pataisyta",tekstas:"Miško medį dabar galima perkelti į kitą miško plytelę. Anksčiau perkėlimas visiems medžiams reikalavo ūkio žemės, tad miške pasodinto nė per plytelę nepastumdavai."},{tipas:"pataisyta",tekstas:"Ežeras ir miškas nebepiešiami kaip suarta dirva — nei savame ūkyje, nei svečiuose pas draugą. Kas nupiešta, tą ir galima dirbti."}]},{data:"2026-08-24",antraste:"Neįmanomų užduočių nebeduodam, sandėlis nebeišsiparduoda per klaidą",eilutes:[{tipas:"pataisyta",tekstas:"Dienos užduotis „Pagauk N žuvų“ nebeduodama tam, kurio ūkyje nėra nė vieno vandens hektaro. Žvejoti be vandens neįmanoma, tad tokia užduotis tiesiog sudegindavo dieną: neįvykdęs vienos iš trijų, negaudavai ir dienos priedo."},{tipas:"pakeista",tekstas:"Sandėlio mygtukas „Parduoti viską“ dabar klausia du kartus: pirmas paspaudimas parodo, kiek vienetų ir už kiek monetų išeis, antras — parduoda. Persigalvojus užtenka perjungti skiltį."},{tipas:"pataisyta",tekstas:"Svečiuojantis pas draugą jo ūkis nebepertvarkomas: anksčiau plytelės būdavo perstumdomos kitaip, nei jis pats jas susidėliojo, o tau dar parodydavo žinutę apie svetimą žemę su žodžiais „žemė tavo“."},{tipas:"pataisyta",tekstas:"Kol Lietuvos žemėlapis dar kraunasi, plytelės nebepamiršta savo žemės rūšies. Retais atvejais dėl to nupirktas ežeras tapdavo paprasta žeme, o žvejyba tam kartui dingdavo."}]},{data:"2026-08-23",versija:"2026-08-23b",antraste:"Dideli pastatai nebenušoka, sandėlis — suprantamas",eilutes:[{tipas:"pataisyta",tekstas:"2×2 pastatas (Vandens bokštas, Silosas, Didelis namas) nebenušoka nuo savo ploto. Kalta buvo technika: ji suardavo ir apsėdavo plyteles PO pastatu, tad kitą kartą įėjus pastatas nebetilpdavo ir susitraukdavo. Jau sugadinti ūkiai atsitaiso patys."},{tipas:"pakeista",tekstas:"Sandėlio talpa nebeskaičiuoja senų monetinių praplėtimų — jų nebeparduodam jau seniai. Nuo šiol talpa = bazinė vieta + Sandėlio ir Siloso pastatai, ir lange parašyta, iš ko ji susideda. Kas buvo pirkęs praplėtimų, vietos turės mažiau: prekės niekur nedingsta, tik kol sandėlis pilnas, naujų nebetilps."},{tipas:"pakeista",tekstas:"Sandėlio langas sutvarkytas: viršuje užimtumas šalia ✕, žemiau paieška su mygtuku Parduoti viską. Pinigų suma ir rikiavimo langelis nuimti."},{tipas:"pataisyta",tekstas:"Lankant draugo ūkį dingo užrašas, kuris slėpdavosi tarp pastatų."}]},{data:"2026-08-23",antraste:"Draugo ūkis žemėlapyje — tikras, o ne mėlynas plotas",eilutes:[{tipas:"nauja",tekstas:"Nuvažiavęs pas draugą per žemėlapį matai TIKRĄ jo ūkį: namą, laukus, medžius ir gyvulius. Anksčiau ten buvo tik mėlynas stačiakampis."},{tipas:"nauja",tekstas:"Atsirado šita skiltis — po kiekvieno atnaujinimo čia parašyta, kas pasikeitė."},{tipas:"pataisyta",tekstas:"Augantys augalai buvo pasislėpę po plytele. Dabar vėl matomi."},{tipas:"pataisyta",tekstas:"Perkėlimu buvo galima apeiti visas statymo taisykles — nunešti kepyklą į ežerą, o žvejybos lieptą į lauko vidurį. Nebegalima."},{tipas:"pataisyta",tekstas:"Vandens statinį (lieptą, tinklus) pagaliau galima perkelti į kitą vietą."},{tipas:"pataisyta",tekstas:"Nuo supurento lauko dingo šviesus apskritimas."},{tipas:"pakeista",tekstas:"Žvejybos lieptas ir pirtis tapo vienetiniai: antras lieptas nieko neduoda, o antra pirtis dvigubindavo dienos poilsį."},{tipas:"pataisyta",tekstas:"Tinklų laikmatis nebebėga, kol jie dar statomi."}]},{data:"2026-08-22",antraste:"Vandens statiniai, krautuvės paieška ir greitesnis laukų darbas",eilutes:[{tipas:"nauja",tekstas:"Vandenyje statoma: Žvejybos lieptas (be jo nebežvejosi), Statomieji tinklai, Žvejo namelis, Vandens malūnas ir Pirtis."},{tipas:"nauja",tekstas:"Pirtyje kartą per parą gali išsipirti — 4 valandas visi darbai duoda 1,5 karto daugiau patirties."},{tipas:"nauja",tekstas:"Krautuvėje atsirado paieška — daikto nebereikia ieškoti akimis."},{tipas:"pakeista",tekstas:"Sandėlio talpa sumažinta tris kartus, o pats sandėlis tapo tobulinamu pastatu."},{tipas:"pataisyta",tekstas:"Purenant ir valant laukus žaidimas strigdavo (vienas veiksmas — 71 ms). Dabar tai trunka apie 3 ms."},{tipas:"pataisyta",tekstas:"Grįžo dingusi grėblio ir kastuvo animacija."},{tipas:"pataisyta",tekstas:"Supurentas laukas pagaliau atrodo kitaip nei paruoštas sėjai."},{tipas:"pataisyta",tekstas:"Šventės pažanga nebedingsta perkrovus žaidimą."},{tipas:"pataisyta",tekstas:"Žiemą atsirado daugiau ko sėti."}]},{data:"2026-08-21",antraste:"Didesnė plytelė, ūkio metraštis ir gyvesnis bendras pasaulis",eilutes:[{tipas:"pakeista",tekstas:"Plytelė padidinta dvigubai — viena dabar tokia, kaip anksčiau keturios."},{tipas:"nauja",tekstas:"Ūkio metraštis: 17 riboženklių su datomis ir tikromis ūkio nuotraukomis."},{tipas:"nauja",tekstas:"Svečiuose pas draugą — veiksmų juosta ir trys nauji veiksmai."},{tipas:"nauja",tekstas:"Sandėlis tapo pastatu, o technika ėmė gesti ir reikalauti remonto."},{tipas:"nauja",tekstas:"Pilnas lauko ratas: po derliaus lauką reikia sugrėbti ir sukasti."},{tipas:"pataisyta",tekstas:"Bendras pasaulis buvo miręs — kaimynai vėl matomi."},{tipas:"pataisyta",tekstas:"Derlius nebedingsta, kai sandėlis pilnas: jis lieka lauke."}]}];function zi(i){return i.versija??i.data}function bc(){const i=$i[0];return i?zi(i):""}function wc(i){if(!i)return $i.slice(0,1);const e=[];for(const t of $i){if(zi(t)<=i)break;e.push(t)}return e}function Sc(i){return wc(i).length>0}function Vw(i,e){return`
